from pathlib import Path
import base64,gzip,re,subprocess,tempfile

GUIDED_JS_B64 = ""
BRIDGE_JS = "(()=>{\n  'use strict';\n  const KEY='geradorCronogramaMpcData';\n  const params=new URLSearchParams(location.search);\n  if(params.get('admin')==='1') return;\n  if(location.pathname!=='/' && !/\\/index\\.html$/.test(location.pathname)) return;\n  let moved=false;\n  function hasAccess(){try{return Boolean(JSON.parse(localStorage.getItem(KEY)||'{}').registered)}catch{return false}}\n  function check(){\n    if(moved||document.body?.classList.contains('admin-view')) return;\n    if(hasAccess()){moved=true;location.replace('/area-usuario.html')}\n  }\n  setTimeout(check,80);\n  const timer=setInterval(()=>{if(moved){clearInterval(timer);return}check()},350);\n})();\n"
ATTRIB_JS = "(()=>{\n  'use strict';\n  async function run(){\n    const parts=location.pathname.split('/').filter(Boolean);\n    const id=(parts.at(-1)||'').toUpperCase();\n    if(!/^[A-Z0-9]{10}$/.test(id)) return;\n    let plan;try{const r=await fetch(`/api/plans?id=${encodeURIComponent(id)}`,{cache:'no-store'});if(!r.ok)return;plan=await r.json()}catch{return}\n    if(!plan?.createdByUser) return;\n    const hero=document.querySelector('.hero');if(!hero)return;\n    const wrap=document.createElement('section');wrap.className='creator-share-banner';\n    const style=document.createElement('style');style.textContent=`.creator-share-banner{max-width:1180px;margin:0 auto 26px;padding:0 24px}.creator-share-card{background:#fff;border:1px solid #E4E8F0;border-left:6px solid #8A5CFF;border-radius:14px;padding:20px 22px;display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center}.creator-share-card strong{display:block;color:#071225;font-family:Georgia,serif;font-size:21px;line-height:1.2}.creator-share-card p{margin:7px 0 0;color:#657086;font-size:14px}.creator-share-btn{background:#8A5CFF;color:#fff!important;border-radius:10px;padding:12px 15px;font-size:12px;font-weight:900;white-space:nowrap;text-decoration:none}@media(max-width:700px){.creator-share-banner{padding:0 14px}.creator-share-card{grid-template-columns:1fr}.creator-share-btn{text-align:center}}`;document.head.appendChild(style);\n    const card=document.createElement('div');card.className='creator-share-card';\n    const copy=document.createElement('div');const strong=document.createElement('strong');strong.textContent=`Eu, ${plan.creatorName||plan.studentName||'estudante'}, gerei este cronograma de estudos gratuitamente com o Gerador de Cronograma MPC.`;const p=document.createElement('p');p.textContent='Quer organizar seus estudos assim também? Gere gratuitamente seu próprio cronograma com matérias, tópicos, subtópicos e uma página pronta para acompanhar no celular.';copy.append(strong,p);\n    const a=document.createElement('a');a.className='creator-share-btn';a.href='/';a.textContent='CRIAR MEU CRONOGRAMA GRATUITAMENTE';card.append(copy,a);wrap.appendChild(card);hero.insertAdjacentElement('afterend',wrap);\n  }\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();\n})();\n"

root=Path('.')
preview=root/'area-usuario-preview.html'
if not preview.exists(): raise SystemExit('area-usuario-preview.html não encontrado')
html=preview.read_text('utf-8')
html=html.replace('<li>Sua área administrativa continuará separada e sem alterações.</li>','<li>Seu acesso continua liberado enquanto você monta o cronograma.</li>')
html=html.replace('<button class="preview-test" id="simulate15">PRÉVIA: SIMULAR 15 MINUTOS</button>','')
html=html.replace('#simulate15{display:none}body.preview-mode #simulate15{display:inline-flex!important}','')
html=re.sub(r'<script>\s*\(\(\)=>\{.*?</script>', '<script src="/guided-user.js"></script>', html, count=1, flags=re.S)
(root/'area-usuario.html').write_text(html,'utf-8')
(root/'guided-user.js').write_bytes(gzip.decompress(base64.b64decode(GUIDED_JS_B64)))
(root/'guided-bridge.js').write_text(BRIDGE_JS,'utf-8')
(root/'user-plan-attribution.js').write_text(ATTRIB_JS,'utf-8')

index=(root/'index.html').read_text('utf-8')
bridge_tag='<script src="/guided-bridge.js" defer></script>'
if bridge_tag not in index:
    index=index.replace('</head>',f'  {bridge_tag}\n</head>',1)
(root/'index.html').write_text(index,'utf-8')

plan=(root/'plano.html').read_text('utf-8')
attrib_tag='<script src="/user-plan-attribution.js" defer></script>'
if attrib_tag not in plan:
    plan=plan.replace('</body>',f'{attrib_tag}\n</body>',1)
(root/'plano.html').write_text(plan,'utf-8')

plans_path=root/'netlify/functions/plans.mjs'
plans=plans_path.read_text('utf-8')
if 'createdByUser:' not in plans:
    marker="    studentName: cleanString(input.studentName, 180),\n"
    repl=marker+"    createdByUser: Boolean(input.createdByUser),\n    creatorName: cleanString(input.creatorName || input.studentName, 180),\n"
    if marker not in plans: raise SystemExit('marker studentName não encontrado em plans.mjs')
    plans=plans.replace(marker,repl,1)
plans_path.write_text(plans,'utf-8')

# Validações estruturais
assert '/guided-bridge.js' in index
assert '/user-plan-attribution.js' in plan
assert 'createdByUser: Boolean(input.createdByUser)' in plans
assert 'OFFER_MS=15*60*1000' in (root/'guided-user.js').read_text('utf-8')
assert 'createdByUser:true' in (root/'guided-user.js').read_text('utf-8')
assert 'simulate15' not in html
assert 'area administrativa continuará' not in html.lower()

# Verificação de sintaxe JavaScript dos novos arquivos
for file in ['guided-user.js','guided-bridge.js','user-plan-attribution.js']:
    subprocess.run(['node','--check',file],check=True)
print('Integração da área guiada validada com sucesso')
